    if isinstance(exc, FileNotFoundError):
        sys.stderr.write(f"open {path}: no such file or directory\n")
    elif isinstance(exc, NotADirectoryError):
        sys.stderr.write(f"open {path}: not a directory\n")
    elif isinstance(exc, IsADirectoryError):
        # Original for /tmp gave "Unknown mimetype for file: /tmp."? Actually for /tmp it gave unknown mimetype, not open error. Let's check.
