def get_extension(path):
    # Case-sensitive, get after last dot
    if '.' not in path:
        return None
    # Split by '.'
    # For /tmp/a.csv, ext = csv
    # For /tmp/test.CSV, ext = CSV (upper)
    ext = path.rsplit('.', 1)[-1]
