    # Simple logfmt parser
    # Format: key=value pairs separated by space, value may be quoted with double quotes
    # Example: time="2015-03-26T01:27:38-04:00" level=debug msg="Started observing beach" animal=walrus number=8
    # We need to handle quoted values with spaces.
    # Implement state machine
    res={}
    i=0
    n=len(line)
    while i<n:
        # Skip spaces
        while i<n and line[i]==' ':
            i+=1
        if i>=n:
            break
        # Read key until =
        key_start=i
        while i<n and line[i]!='=' and line[i]!=' ':
            i+=1
        if i>=n or line[i]!='=':
            # No =, treat rest as? Actually logfmt may have bare keys? In original, it seemed to parse only key=value.
            # Skip to next space
            while i<n and line[i]!=' ':
                i+=1
            continue
        key=line[key_start:i]
        i+=1 # skip =
        if i>=n:
            res[key]=""
            break
        if line[i]=='"':
            # Quoted value
            i+=1
            val_start=i
            # Find closing quote, handling escaped?
            # In logfmt, quotes inside may be escaped? For simplicity, find next unescaped quote
            while i<n:
                if line[i]=='"' and (i==0 or line[i-1]!='\\'):
                    break
                i+=1
            val=line[val_start:i]
            # Unescape? Not needed
            if i<n and line[i]=='"':
                i+=1
            res[key]=val
        else:
            # Unquoted value until space
            val_start=i
            while i<n and line[i]!=' ':
                i+=1
            val=line[val_start:i]
            res[key]=val
