        error_unknown_mimetype(path)

    def read_long(buf, pos):
        n=0
        shift=0
        while True:
            if pos>=len(buf):
                raise Exception("EOF")
            b=buf[pos]
            pos+=1
            n|=(b&0x7F)<<shift
            if not (b&0x80):
                break
            shift+=7
        val=(n>>1) ^ -(n&1)
        return val,pos

    def read_bytes_inner(buf,pos):
        l,pos=read_long(buf,pos)
        if l<0:
            raise Exception("negative length")
        b=buf[pos:pos+l]
        pos+=l
        return b,pos

    def read_string_inner(buf,pos):
        b,pos=read_bytes_inner(buf,pos)
        return b.decode('utf-8'),pos

    def snappy_decompress_block(block):
        if len(block)<4:
            return b""
        comp = block[:-4]
        i=0
        length=0
        shift=0
        while True:
            if i>=len(comp):
                break
            b=comp[i]
            i+=1
            length |= (b & 0x7F) << shift
            if not (b & 0x80):
                break
            shift+=7
        src = comp[i:]
        dst = bytearray()
        p=0
        while p < len(src):
            tag = src[p]
            p+=1
            typ = tag & 0x03
            if typ == 0:
                l = (tag >> 2)
                if l < 60:
                    l+=1
                else:
                    nbytes = l - 59
                    extra=0
                    for j in range(nbytes):
                        if p+j >= len(src):
                            break
                        extra |= src[p+j] << (j*8)
                    p+=nbytes
                    l = extra+1
                if p+l > len(src):
                    # truncated?
                    dst.extend(src[p:])
                    break
                dst.extend(src[p:p+l])
                p+=l
            elif typ == 1:
                l = ((tag >> 2) & 0x07) + 4
                if p>=len(src):
                    break
                off = ((tag >> 5) << 8) | src[p]
                p+=1
                for _ in range(l):
                    if off>len(dst) or off<=0:
                        break
                    dst.append(dst[-off])
            elif typ == 2:
                l = (tag >> 2) + 1
                if p+1>=len(src):
                    break
                off = src[p] | (src[p+1] << 8)
                p+=2
                for _ in range(l):
                    if off>len(dst) or off<=0:
                        break
                    dst.append(dst[-off])
            else:
                l = (tag >> 2) + 1
                if p+3>=len(src):
                    break
                off = src[p] | (src[p+1] << 8) | (src[p+2] << 16) | (src[p+3] << 24)
                p+=4
                for _ in range(l):
                    if off>len(dst) or off<=0:
                        break
                    dst.append(dst[-off])
        return bytes(dst)

    # Check magic
    if len(data)<4 or data[0:3]!=b'Obj' or data[3]!=1:
        # Original error for invalid avro: "cannot create OCFReader: cannot read OCF header with invalid magic bytes: \"...\""
        # We'll try to mimic: get first few chars as string
