        sys.stderr.write(f"cannot create OCFReader: {e}\n")
        sys.exit(1)
    schema=None
    codec=b'null'
    for _ in range(cnt):
        try:
            k,pos=read_string_inner(data,pos)
            v,pos=read_bytes_inner(data,pos)
        except Exception as e:
            sys.stderr.write(f"cannot create OCFReader: {e}\n")
            sys.exit(1)
        if k=='avro.schema':
            try:
                schema=json.loads(v.decode())
            except:
                schema=None
        elif k=='avro.codec':
            codec=v
    try:
        end,pos=read_long(data,pos)
        sync=data[pos:pos+16]
        pos+=16
    except Exception as e:
        sys.stderr.write(f"cannot create OCFReader: {e}\n")
        sys.exit(1)

    if schema is None:
        sys.stderr.write("cannot create OCFReader: no schema\n")
        sys.exit(1)

    # helpers for decoding
    def decode_type(buf, p, typ):
        if isinstance(typ, list):
            idx, p = read_long(buf, p)
            return decode_type(buf, p, typ[idx])
        if isinstance(typ, dict):
            t=typ.get('type')
            if t=='record':
                out={}
                for field in typ.get('fields',[]):
                    name=field['name']
                    ftyp=field['type']
                    val,p = decode_type(buf, p, ftyp)
                    out[name]=val
                return out,p
            elif t=='array':
                # array: count, then items, then 0
                # For simplicity not needed for test file
                arr=[]
                while True:
                    count,p = read_long(buf,p)
                    if count==0:
                        break
                    if count<0:
                        count=-count
                        # size
                        _,p = read_long(buf,p)
                    for _ in range(count):
                        val,p = decode_type(buf,p, typ.get('items'))
                        arr.append(val)
                return arr,p
            elif t=='map':
                # not needed
                m={}
                while True:
                    count,p = read_long(buf,p)
                    if count==0:
                        break
                    if count<0:
                        count=-count
                        _,p = read_long(buf,p)
                    for _ in range(count):
                        key,p = read_string_inner(buf,p)
                        val,p = decode_type(buf,p, typ.get('values'))
                        m[key]=val
                return m,p
            else:
                raise Exception(f"unsupported type dict {typ}")
        # string type name
        if typ=='null':
            return None,p
        if typ=='string':
            s,p = read_string_inner(buf,p)
            return s,p
        if typ=='long':
            v,p = read_long(buf,p)
            return v,p
        if typ=='int':
            v,p = read_long(buf,p)
            return v,p
        if typ=='double':
            import struct
            v = struct.unpack('<d', buf[p:p+8])[0]
            p+=8
            return v,p
        if typ=='float':
            import struct
            v = struct.unpack('<f', buf[p:p+4])[0]
            p+=4
            return v,p
        if typ=='boolean':
            b=buf[p]
            p+=1
            return bool(b),p
        if typ=='bytes':
            b,p = read_bytes_inner(buf,p)
            return b,p
        raise Exception(f"unknown type {typ}")

    rows=[]
    while pos < len(data):
        try:
            count,pos=read_long(data,pos)
        except:
            break
        if count==0:
            # end of file?
            break
        try:
            size,pos=read_long(data,pos)
        except:
            break
        if pos+size > len(data):
            break
        block=data[pos:pos+size]
        pos+=size
        # sync
        if pos+16 <= len(data):
            sync2=data[pos:pos+16]
            pos+=16
        else:
            sync2=b""
        # decompress based on codec
        if codec==b'snappy':
            try:
                decomp = snappy_decompress_block(block)
            except Exception as e:
                sys.stderr.write(f"snappy decompress error: {e}\n")
                sys.exit(1)
        elif codec==b'deflate':
            import zlib
            try:
                decomp = zlib.decompress(block)
            except Exception as e:
                sys.stderr.write(f"deflate error: {e}\n")
                sys.exit(1)
        else: # null
            decomp = block
        dpos=0
        for _ in range(count):
            try:
                rec,dpos = decode_type(decomp, dpos, schema)
                rows.append(rec)
            except Exception as e:
                # If fails, break
                # print("decode error", e)
                break
    return rows

