# Schema inference
def infer_scalar_type(value):
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, dict):
        return "object"
    if isinstance(value, list):
        return "array"
    return "unknown"

def infer_shape_from_values(values):
    # values: list of values (could include None for missing)
    # Returns shape dict
    # Collect shapes for each value
    shapes=[]
    for v in values:
        if v is None:
            shapes.append({"kind":"scalar","scalar":"null"})
        elif isinstance(v, bool):
            shapes.append({"kind":"scalar","scalar":"boolean"})
        elif isinstance(v, (int, float)):
            shapes.append({"kind":"scalar","scalar":"number"})
        elif isinstance(v, str):
            shapes.append({"kind":"scalar","scalar":"string"})
        elif isinstance(v, dict):
            # Infer object shape
            # For each key in dict, collect values? But here v is single dict, we need to infer its internal structure from this single dict?
            # Actually for object values, we should infer shape of the object as object with its fields.
