    border="+" + "+".join("-"*(w+2) for w in widths) + "+"
    lines=[border]
    header_cells=[]
    for i,h in enumerate(headers):
        W=widths[i]
        diff=W-len(h)
        left=diff//2
        right=diff-left
        centered=" "*left + h + " "*right
        header_cells.append(" " + centered + " ")
    lines.append("|" + "|".join(header_cells) + "|")
    lines.append(border)
    for r in str_rows:
        cells=[]
        for i in range(cols):
            val=r[i] if i < len(r) else ""
            W=widths[i]
            # numeric detection
            is_num=False
            try:
