# XLSX and ODS readers
def read_xlsx_file(path):
    try:
        zf = zipfile.ZipFile(path)
    except zipfile.BadZipFile:
        sys.stderr.write("zip: not a valid zip file\n")
        sys.exit(1)
    except FileNotFoundError as e:
        error_open_file(path, e)
    except NotADirectoryError as e:
        error_open_file(path, e)
    except IsADirectoryError as e:
        error_unknown_mimetype(path)
    # Read workbook.xml to get sheets
    try:
        wb_data = zf.read("xl/workbook.xml")
    except KeyError:
        # No workbook? Treat as error
        sys.stderr.write("zip: not a valid zip file\n")
        sys.exit(1)
    # Parse workbook
    try:
        root = ET.fromstring(wb_data)
    except Exception:
        sys.stderr.write("zip: not a valid zip file\n")
        sys.exit(1)
    ns = {'main':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
    sheets = root.findall('.//main:sheet', ns)
    sheet_names=[]
    sheet_rIds=[]
    for s in sheets:
        name = s.get('name')
        sheet_names.append(name)
        rId = s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        sheet_rIds.append(rId)
    # Read workbook rels to map rId to file
    try:
        rels_data = zf.read("xl/_rels/workbook.xml.rels")
        rels_root = ET.fromstring(rels_data)
        ns_rel = {'main':'http://schemas.openxmlformats.org/package/2006/relationships'}
        rId_to_target={}
        for rel in rels_root.findall('main:Relationship', ns_rel):
            rId_to_target[rel.get('Id')] = rel.get('Target')
    except:
        rId_to_target={}
    # Shared strings
    strings=[]
    try:
        ss_data = zf.read("xl/sharedStrings.xml")
        ss_root = ET.fromstring(ss_data)
        # <sst><si><t>...</t></si></sst> or <si><r><t>...
        for si in ss_root.findall('.//main:t', ns):
            # Actually need to handle si containing multiple t?
            # For simplicity, collect all t inside si and join?
            # But for multiple sheets file, sharedStrings contains list
            pass
        # Better: iterate si
        for si in ss_root.findall('main:si', ns):
            # si may have t or r which contains t
            t_elems = si.findall('main:t', ns)
            if t_elems:
                # Join all t text
                txt = ''.join([t.text if t.text is not None else '' for t in t_elems])
                strings.append(txt)
            else:
                # Look for r
                r_elems = si.findall('main:r', ns)
                txt=''
                for r in r_elems:
                    t = r.find('main:t', ns)
                    if t is not None and t.text is not None:
                        txt+=t.text
                strings.append(txt)
    except KeyError:
        strings=[]
    # Now read each sheet
    sheets_data={}
    for idx, (name, rId) in enumerate(zip(sheet_names, sheet_rIds)):
        target = rId_to_target.get(rId)
        if target is None:
            # Fallback: xl/worksheets/sheet{i+1}.xml
            target = f"worksheets/sheet{idx+1}.xml"
        # target may be like "worksheets/sheet1.xml" or "xl/worksheets/..."? In workbook.xml.rels Target is relative to xl/
        if not target.startswith("xl/"):
            # It's relative to xl/
            sheet_path = f"xl/{target}"
        else:
            sheet_path = target
        try:
            sheet_data = zf.read(sheet_path)
        except KeyError:
            # Try alternative
            try:
                sheet_data = zf.read(f"xl/worksheets/sheet{idx+1}.xml")
            except:
                continue
        try:
            root_sheet = ET.fromstring(sheet_data)
        except:
            continue
        sheet_ns = {'main':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
        sheetData = root_sheet.find('.//main:sheetData', sheet_ns)
        if sheetData is None:
            continue
        rows=[]
        for row_elem in sheetData.findall('main:row', sheet_ns):
            cells=[]
            # Need to handle cells in order, but also need to handle missing cells? For simplicity, just collect in order encountered.
            # Also need to handle column indexes to fill gaps? For simplicity, ignore gaps.
            for c_elem in row_elem.findall('main:c', sheet_ns):
                t = c_elem.get('t')
                v_elem = c_elem.find('main:v', sheet_ns)
                if v_elem is None:
                    # Check inlineStr
                    is_elem = c_elem.find('main:is', sheet_ns)
                    if is_elem is not None:
                        t_elem = is_elem.find('main:t', sheet_ns)
                        if t_elem is not None and t_elem.text is not None:
                            cells.append(t_elem.text)
                        else:
                            cells.append("")
                    else:
                        cells.append("")
                    continue
                v = v_elem.text
                if v is None:
                    cells.append("")
                    continue
                if t == 's':
                    try:
                        idx_s = int(v)
                        if 0 <= idx_s < len(strings):
                            cells.append(strings[idx_s])
                        else:
                            cells.append(v)
                    except:
                        cells.append(v)
                else:
                    cells.append(v)
            rows.append(cells)
        sheets_data[name]=rows

    # Now convert to list of dicts per sheet
    # For single sheet, return array of objects
    # For multiple sheets, return dict mapping sheet name to array
    if len(sheets_data)==0:
        return []
    if len(sheets_data)==1:
        # Single sheet
        name = list(sheets_data.keys())[0]
        rows = sheets_data[name]
        if len(rows)==0:
            return []
        header = rows[0]
        data_rows = rows[1:]
        result=[]
        for dr in data_rows:
            obj={}
            for i, h in enumerate(header):
                if i < len(dr):
                    obj[h]=dr[i]
                else:
                    obj[h]=""
            result.append(obj)
        return result
    else:
        # Multiple sheets
        result={}
        for name, rows in sheets_data.items():
            if len(rows)==0:
                result[name]=[]
                continue
            header=rows[0]
            data_rows=rows[1:]
            arr=[]
            for dr in data_rows:
                obj={}
                for i,h in enumerate(header):
                    if i < len(dr):
                        obj[h]=dr[i]
                    else:
                        obj[h]=""
                arr.append(obj)
            result[name]=arr
        return result

