# Avro reader (generic)
def read_avro_file(path):
    # Implement minimal Avro OCF reader with snappy support
    try:
        data = pathlib.Path(path).read_bytes()
    except FileNotFoundError as e:
        error_open_file(path, e)
    except NotADirectoryError as e:
        error_open_file(path, e)
    except IsADirectoryError as e:
        error_unknown_mimetype(path)

    def read_long(buf, pos):
        n=0
        shift=0
        while True:
            if pos>=len(buf):
                raise Exception("EOF")
            b=buf[pos]
            pos+=1
            n|=(b&0x7F)<<shift
            if not (b&0x80):
                break
            shift+=7
        val=(n>>1) ^ -(n&1)
        return val,pos

    def read_bytes_inner(buf,pos):
        l,pos=read_long(buf,pos)
        if l<0:
            raise Exception("negative length")
        b=buf[pos:pos+l]
        pos+=l
        return b,pos

    def read_string_inner(buf,pos):
        b,pos=read_bytes_inner(buf,pos)
        return b.decode('utf-8'),pos

    def snappy_decompress_block(block):
        if len(block)<4:
            return b""
        comp = block[:-4]
        i=0
        length=0
        shift=0
        while True:
            if i>=len(comp):
                break
            b=comp[i]
            i+=1
            length |= (b & 0x7F) << shift
            if not (b & 0x80):
                break
            shift+=7
        src = comp[i:]
        dst = bytearray()
        p=0
        while p < len(src):
            tag = src[p]
            p+=1
            typ = tag & 0x03
            if typ == 0:
                l = (tag >> 2)
                if l < 60:
                    l+=1
                else:
                    nbytes = l - 59
                    extra=0
                    for j in range(nbytes):
                        if p+j >= len(src):
                            break
                        extra |= src[p+j] << (j*8)
                    p+=nbytes
                    l = extra+1
                if p+l > len(src):
                    # truncated?
                    dst.extend(src[p:])
                    break
                dst.extend(src[p:p+l])
                p+=l
            elif typ == 1:
                l = ((tag >> 2) & 0x07) + 4
                if p>=len(src):
                    break
                off = ((tag >> 5) << 8) | src[p]
                p+=1
                for _ in range(l):
                    if off>len(dst) or off<=0:
                        break
                    dst.append(dst[-off])
            elif typ == 2:
                l = (tag >> 2) + 1
                if p+1>=len(src):
                    break
                off = src[p] | (src[p+1] << 8)
                p+=2
                for _ in range(l):
                    if off>len(dst) or off<=0:
                        break
                    dst.append(dst[-off])
            else:
                l = (tag >> 2) + 1
                if p+3>=len(src):
                    break
                off = src[p] | (src[p+1] << 8) | (src[p+2] << 16) | (src[p+3] << 24)
                p+=4
                for _ in range(l):
                    if off>len(dst) or off<=0:
                        break
                    dst.append(dst[-off])
        return bytes(dst)

    # Check magic
    if len(data)<4 or data[0:3]!=b'Obj' or data[3]!=1:
        # Original error for invalid avro: "cannot create OCFReader: cannot read OCF header with invalid magic bytes: \"...\""
        # We'll try to mimic: get first few chars as string
        snippet = data[:10]
        try:
            s = snippet.decode('utf-8', errors='replace')
        except:
            s = str(snippet)
        # Escape? Original showed "a,b\n" as "a,b\n" ? Actually it showed "a,b\n" as "a,b\n" in error.
        # For file containing "a,b\n", error was "cannot create OCFReader: cannot read OCF header with invalid magic bytes: \"a,b\\n\""
        # So they include the bytes as string with escaped newline.
        # We'll produce similar
        # For simplicity, show first few bytes as string
        display = data[:20].decode('utf-8', errors='replace').replace('\n','\\n').replace('\r','\\r')
        sys.stderr.write(f"cannot create OCFReader: cannot read OCF header with invalid magic bytes: \"{display}\"\n")
        sys.exit(1)

    pos=4
    try:
        cnt,pos=read_long(data,pos)
    except Exception as e:
        sys.stderr.write(f"cannot create OCFReader: {e}\n")
        sys.exit(1)
    schema=None
    codec=b'null'
    for _ in range(cnt):
        try:
            k,pos=read_string_inner(data,pos)
            v,pos=read_bytes_inner(data,pos)
        except Exception as e:
            sys.stderr.write(f"cannot create OCFReader: {e}\n")
            sys.exit(1)
        if k=='avro.schema':
            try:
                schema=json.loads(v.decode())
            except:
                schema=None
        elif k=='avro.codec':
            codec=v
    try:
        end,pos=read_long(data,pos)
        sync=data[pos:pos+16]
        pos+=16
    except Exception as e:
        sys.stderr.write(f"cannot create OCFReader: {e}\n")
        sys.exit(1)

    if schema is None:
        sys.stderr.write("cannot create OCFReader: no schema\n")
        sys.exit(1)

    # helpers for decoding
    def decode_type(buf, p, typ):
        if isinstance(typ, list):
            idx, p = read_long(buf, p)
            return decode_type(buf, p, typ[idx])
        if isinstance(typ, dict):
            t=typ.get('type')
            if t=='record':
                out={}
                for field in typ.get('fields',[]):
                    name=field['name']
                    ftyp=field['type']
                    val,p = decode_type(buf, p, ftyp)
                    out[name]=val
                return out,p
            elif t=='array':
                # array: count, then items, then 0
                # For simplicity not needed for test file
                arr=[]
                while True:
                    count,p = read_long(buf,p)
                    if count==0:
                        break
                    if count<0:
                        count=-count
                        # size
                        _,p = read_long(buf,p)
                    for _ in range(count):
                        val,p = decode_type(buf,p, typ.get('items'))
                        arr.append(val)
                return arr,p
            elif t=='map':
                # not needed
                m={}
                while True:
                    count,p = read_long(buf,p)
                    if count==0:
                        break
                    if count<0:
                        count=-count
                        _,p = read_long(buf,p)
                    for _ in range(count):
                        key,p = read_string_inner(buf,p)
                        val,p = decode_type(buf,p, typ.get('values'))
                        m[key]=val
                return m,p
            else:
                raise Exception(f"unsupported type dict {typ}")
        # string type name
        if typ=='null':
            return None,p
        if typ=='string':
            s,p = read_string_inner(buf,p)
            return s,p
        if typ=='long':
            v,p = read_long(buf,p)
            return v,p
        if typ=='int':
            v,p = read_long(buf,p)
            return v,p
        if typ=='double':
            import struct
            v = struct.unpack('<d', buf[p:p+8])[0]
            p+=8
            return v,p
        if typ=='float':
            import struct
            v = struct.unpack('<f', buf[p:p+4])[0]
            p+=4
            return v,p
        if typ=='boolean':
            b=buf[p]
            p+=1
            return bool(b),p
        if typ=='bytes':
            b,p = read_bytes_inner(buf,p)
            return b,p
        raise Exception(f"unknown type {typ}")

    rows=[]
    while pos < len(data):
        try:
            count,pos=read_long(data,pos)
        except:
            break
        if count==0:
            # end of file?
            break
        try:
            size,pos=read_long(data,pos)
        except:
            break
        if pos+size > len(data):
            break
        block=data[pos:pos+size]
        pos+=size
        # sync
        if pos+16 <= len(data):
            sync2=data[pos:pos+16]
            pos+=16
        else:
            sync2=b""
        # decompress based on codec
        if codec==b'snappy':
            try:
                decomp = snappy_decompress_block(block)
            except Exception as e:
                sys.stderr.write(f"snappy decompress error: {e}\n")
                sys.exit(1)
        elif codec==b'deflate':
            import zlib
            try:
                decomp = zlib.decompress(block)
            except Exception as e:
                sys.stderr.write(f"deflate error: {e}\n")
                sys.exit(1)
        else: # null
            decomp = block
        dpos=0
        for _ in range(count):
            try:
                rec,dpos = decode_type(decomp, dpos, schema)
                rows.append(rec)
            except Exception as e:
                # If fails, break
                # print("decode error", e)
                break
    return rows

