# Schema inference
def infer_scalar_type(value):
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, dict):
        return "object"
    if isinstance(value, list):
        return "array"
    return "unknown"

def infer_shape_from_values(values):
    # values: list of values (could include None for missing)
    # Returns shape dict
    # Collect shapes for each value
    shapes=[]
    for v in values:
        if v is None:
            shapes.append({"kind":"scalar","scalar":"null"})
        elif isinstance(v, bool):
            shapes.append({"kind":"scalar","scalar":"boolean"})
        elif isinstance(v, (int, float)):
            shapes.append({"kind":"scalar","scalar":"number"})
        elif isinstance(v, str):
            shapes.append({"kind":"scalar","scalar":"string"})
        elif isinstance(v, dict):
            # Infer object shape
            # For each key in dict, collect values? But here v is single dict, we need to infer its internal structure from this single dict?
            # Actually for object values, we should infer shape of the object as object with its fields.
            # For each field in dict, infer its shape from its single value? But we need to handle multiple dicts elsewhere.
            # For now, if all values are dicts, we will merge them in outer function.
            # Here we treat single dict as object shape with its fields each scalar? We need recursive.
            # We'll call infer_object_shape([v])
            obj_shape = infer_object_shape([v])
            shapes.append(obj_shape)
        elif isinstance(v, list):
            # Infer array shape from its elements
            if len(v)==0:
                shapes.append({"kind":"array","array":{"kind":"unknown"}})
            else:
                # Infer shape of elements
                elem_shape = infer_shape_from_values(v)
                shapes.append({"kind":"array","array":elem_shape})
        else:
            shapes.append({"kind":"unknown"})
    # Deduplicate shapes
    # For scalar, dedup by scalar type
    uniq={}
    for s in shapes:
        key=json.dumps(s, sort_keys=True)
        uniq[key]=s
    uniq_list=list(uniq.values())
    if len(uniq_list)==0:
        return {"kind":"unknown"}
    if len(uniq_list)==1:
        return uniq_list[0]
    # Multiple => varied
    # For varied, need to sort? Original order for varied seems not sorted? For log, varied order was [string,null] ? In schema for log, size varied had string then null? Actually earlier we saw size varied had string then null? The order was string then null? Let's check: For size field, varied had string then null? In earlier log schema: size varied had string then null? Yes: first varied entry string, second null.
    # For our implementation, we can keep order of appearance?
    return {"kind":"varied","varied":uniq_list}

def infer_object_shape(dicts):
    # dicts: list of dicts
    # Union of keys
    all_keys=set()
    for d in dicts:
        if isinstance(d, dict):
            all_keys.update(d.keys())
    # For each key, collect values (including None for missing)
    obj={}
    for k in sorted(all_keys): # sorted for deterministic? Original JSON output for schema seemed not sorted? But pretty was sorted.
        vals=[]
        for d in dicts:
            if isinstance(d, dict) and k in d:
                vals.append(d[k])
            else:
                vals.append(None) # missing -> null
        shape = infer_shape_from_values(vals)
        obj[k]=shape
    return {"kind":"object","object":obj}

def infer_schema(data):
    # data can be list, dict, or other
    if isinstance(data, list):
        if len(data)==0:
            return {"kind":"array","array":{"kind":"unknown"}}
        # Check if all elements are dicts?
        # For Top-level array of objects -> array of object
        # For array of scalars -> array of scalar
        # We'll infer shape of elements
        elem_shape = infer_shape_from_values(data)
        # But if elements are dicts, elem_shape will be object (if we handle correctly via infer_shape_from_values that merges dicts)
        # However infer_shape_from_values for list of dicts: each dict's shape is object, so it will be varied of objects? We need to merge dicts.
        # So we need special handling: if all elements are dicts, infer object shape from list of dicts
        if all(isinstance(x, dict) for x in data):
            obj_shape = infer_object_shape(data)
            return {"kind":"array","array":obj_shape}
        else:
            # For array of mixed types, elem_shape may be varied etc.
            # The outer array's shape is array of elem_shape
            # But if data is list of dicts and some dicts have different keys, infer_object_shape handles union.
            # For non-dicts, we use elem_shape
            # Actually infer_shape_from_values already handles list of dicts as object? Let's see: for each dict, we get object shape, then dedup, if all same keys, it will be single object shape, so array of that.
            # But if dicts have different keys, their object shapes will be different (different keys), so uniq_list will have multiple object shapes, leading to varied of objects. However original schema for log with varying keys still had single object with varied fields, not varied of objects. So we should use infer_object_shape for all dicts, not infer_shape_from_values for dicts individually.

            # So if all elements are dicts, we already handled above with infer_object_shape. Otherwise, use elem_shape.
            return {"kind":"array","array":elem_shape}
    elif isinstance(data, dict):
        # Object mapping to array etc (for multi-sheet)
        # If dict values are arrays, we need to infer each value's schema
        obj={}
        for k in sorted(data.keys()):
            v=data[k]
            obj[k]=infer_schema(v)
        return {"kind":"object","object":obj}
    else:
        # Scalar? But top-level scalar? For file with single object {"a":1}, we already handle as dict case.
        # For primitive, return scalar?
        if data is None:
            return {"kind":"scalar","scalar":"null"}
        if isinstance(data, bool):
            return {"kind":"scalar","scalar":"boolean"}
        if isinstance(data, (int,float)):
