def infer_shape_from_values(values):
    shapes=[]
    for v in values:
        if v is None:
            shapes.append({"kind":"scalar","scalar":"null"})
        elif isinstance(v, bool):
            shapes.append({"kind":"scalar","scalar":"boolean"})
        elif isinstance(v, (int, float)):
            shapes.append({"kind":"scalar","scalar":"number"})
        elif isinstance(v, str):
            shapes.append({"kind":"scalar","scalar":"string"})
        elif isinstance(v, dict):
            obj_shape = infer_object_shape([v])
            shapes.append(obj_shape)
        elif isinstance(v, list):
            if len(v)==0:
                shapes.append({"kind":"array","array":{"kind":"unknown"}})
            else:
                elem_shape = infer_shape_from_values(v)
                shapes.append({"kind":"array","array":elem_shape})
        else:
            shapes.append({"kind":"unknown"})
    uniq={}
    for s in shapes:
        key=json.dumps(s, sort_keys=True)
        uniq[key]=s
    uniq_list=list(uniq.values())
    if len(uniq_list)==0:
        return {"kind":"unknown"}
    if len(uniq_list)==1:
        return uniq_list[0]
    return {"kind":"varied","varied":uniq_list}

def infer_object_shape(dicts):
    all_keys=set()
    for d in dicts:
        if isinstance(d, dict):
            all_keys.update(d.keys())
    obj={}
    for k in sorted(all_keys):
        vals=[]
        for d in dicts:
            if isinstance(d, dict) and k in d:
                vals.append(d[k])
            else:
                vals.append(None)
        shape = infer_shape_from_values(vals)
        obj[k]=shape
    return {"kind":"object","object":obj}

def infer_schema(data):
    if isinstance(data, list):
        if len(data)==0:
            return {"kind":"array","array":{"kind":"unknown"}}
        if all(isinstance(x, dict) for x in data):
            obj_shape = infer_object_shape(data)
            return {"kind":"array","array":obj_shape}
        else:
            elem_shape = infer_shape_from_values(data)
            return {"kind":"array","array":elem_shape}
    elif isinstance(data, dict):
        obj={}
        for k in sorted(data.keys()):
            v=data[k]
            obj[k]=infer_schema(v)
        return {"kind":"object","object":obj}
    else:
        if data is None:
            return {"kind":"scalar","scalar":"null"}
        if isinstance(data, bool):
            return {"kind":"scalar","scalar":"boolean"}
        if isinstance(data, (int,float)):
            return {"kind":"scalar","scalar":"number"}
        if isinstance(data, str):
            return {"kind":"scalar","scalar":"string"}
        return {"kind":"unknown"}

def schema_to_pretty(shape, indent=0):
    lines=[]
    prefix="  "*indent
    kind=shape.get("kind")
    if kind=="array":
        lines.append(f"{prefix}Array of")
        child=shape.get("array")
        if child:
            lines.extend(schema_to_pretty(child, indent+1))
        else:
            lines.append(f"{'  '*(indent+1)}Unknown")
    elif kind=="object":
        lines.append(f"{prefix}Object of")
        obj=shape.get("object",{})
        for k in sorted(obj.keys()):
            v=obj[k]
            lines.append(f"{'  '*(indent+1)}{k} of")
            lines.extend(schema_to_pretty(v, indent+2))
    elif kind=="scalar":
        scalar=shape.get("scalar","unknown")
        lines.append(f"{prefix}{scalar}")
    elif kind=="varied":
        lines.append(f"{prefix}Varied of")
        varied=shape.get("varied",[])
        for idx, sub in enumerate(varied):
            sub_lines=schema_to_pretty(sub, indent+1)
            if idx < len(varied)-1:
                sub_lines[-1] = sub_lines[-1] + " or"
            lines.extend(sub_lines)
    elif kind=="unknown":
        lines.append(f"{prefix}Unknown")
    else:
        lines.append(f"{prefix}Unknown")
    return lines

def format_table(headers, rows):
    # rows: list of dicts or list of tuples? We will get headers and rows as list of values
    # Convert rows to string for width: bool->true/false lower, None->null
    str_rows=[]
    for r in rows:
        if isinstance(r, dict):
            # Need to map headers to values
            sr=[]
            for h in headers:
                v=r.get(h)
                if v is None:
                    sr.append("null")
                elif isinstance(v,bool):
                    sr.append(str(v).lower())
                else:
                    sr.append(str(v))
            str_rows.append(sr)
        else:
            # list/tuple
            sr=[]
            for c in r:
                if c is None:
                    sr.append("null")
                elif isinstance(c,bool):
                    sr.append(str(c).lower())
                else:
                    sr.append(str(c))
            str_rows.append(sr)
    cols=len(headers)
    widths=[]
    for i in range(cols):
        max_len=len(headers[i])
        for r in str_rows:
            if i < len(r):
                max_len=max(max_len, len(r[i]))
        widths.append(max_len)
    border="+" + "+".join("-"*(w+2) for w in widths) + "+"
    lines=[border]
    header_cells=[]
    for i,h in enumerate(headers):
        W=widths[i]
        diff=W-len(h)
        left=diff//2
        right=diff-left
        centered=" "*left + h + " "*right
        header_cells.append(" " + centered + " ")
    lines.append("|" + "|".join(header_cells) + "|")
    lines.append(border)
    for r in str_rows:
        cells=[]
        for i in range(cols):
            val=r[i] if i < len(r) else ""
            W=widths[i]
            is_num=False
            try:
                float(val)
                if val not in ("null","true","false",""):
                    is_num=True
            except:
                is_num=False
            if is_num:
                padded=val.rjust(W)
            else:
                padded=val.ljust(W)
            cells.append(" " + padded + " ")
        lines.append("|" + "|".join(cells) + "|")
    lines.append(border)
    n=len(rows)
    lines.append(f"({n} row)" if n==1 else f"({n} rows)")
    return "\n".join(lines)

def compute_hash_of_files(file_paths, stdin_data=None):
    h=hashlib.sha1()
    if stdin_data is not None:
        h.update(stdin_data)
    for fp in file_paths:
        try:
            with open(fp, 'rb') as f:
                while True:
                    chunk=f.read(8192)
                    if not chunk:
                        break
                    h.update(chunk)
        except:
            pass
    return h.hexdigest()

