HELP_TEXT = """dsq (Version latest) - commandline SQL engine for data files

Usage:  dsq [file...] $query
        dsq $file [query]
        cat $file | dsq -s $filetype [query]
        dsq $file -f $queryfile

dsq is a tool for running SQL on one or more data files. It uses
SQLite's SQL dialect. Files as tables are accessible via "{N}" where N
is the 0-based index of the file in the commandline.

The shorthand "{}" is replaced with "{0}".

Examples:

    # This simply dumps the CSV as JSON
    $ dsq test.csv

    # This dumps the first 10 rows of the parquet file as JSON.
    $ dsq data.parquet "SELECT * FROM {} LIMIT 10"

    # This joins two datasets of differing origin types (CSV and JSON).
    $ dsq testdata/join/users.csv testdata/join/ages.json \\
          "select {0}.name, {1}.age from {0} join {1} on {0}.id = {1}.id"

See the repo for more details: https://github.com/multiprocessio/dsq
"""
VERSION_TEXT = "dsq latest\n"

KNOWN_EXTS = ["csv","tsv","json","jsonl","ndjson","logfmt","parquet","orc","avro","xlsx","xls","ods"]
KNOWN_STDIN_FORMATS = ["csv","tsv","json","jsonl","ndjson","logfmt","parquet","orc","avro","xlsx","xls","ods"]

def print_help():
    sys.stderr.write(HELP_TEXT)
    sys.exit(0)

def print_version():
    sys.stdout.write(VERSION_TEXT)
    sys.exit(0)

def error_unknown_mimetype(path):
    sys.stderr.write(f"Unknown mimetype for file: {path}.\n")
    sys.exit(1)

def error_open_file(path, exc):
    if isinstance(exc, FileNotFoundError):
        sys.stderr.write(f"open {path}: no such file or directory\n")
    elif isinstance(exc, NotADirectoryError):
        sys.stderr.write(f"open {path}: not a directory\n")
    elif isinstance(exc, IsADirectoryError):
        error_unknown_mimetype(path)
    else:
        # Generic
        sys.stderr.write(f"open {path}: {exc}\n")
    sys.exit(1)

def get_extension(path):
    if '.' not in path:
        return None
    return path.rsplit('.', 1)[-1]

def is_known_extension(ext):
    return ext in KNOWN_EXTS

def parse_logfmt_line(line):
    res={}
    i=0
    n=len(line)
    while i<n:
        while i<n and line[i]==' ':
            i+=1
        if i>=n:
            break
        key_start=i
        while i<n and line[i]!='=' and line[i]!=' ':
            i+=1
        if i>=n or line[i]!='=':
            while i<n and line[i]!=' ':
                i+=1
            continue
        key=line[key_start:i]
        i+=1
        if i>=n:
            res[key]=""
            break
        if line[i]=='"':
            i+=1
            val_start=i
            while i<n:
                if line[i]=='"' and (i==0 or line[i-1]!='\\'):
                    break
                i+=1
            val=line[val_start:i]
            if i<n and line[i]=='"':
                i+=1
            res[key]=val
        else:
            val_start=i
            while i<n and line[i]!=' ':
                i+=1
            val=line[val_start:i]
            res[key]=val
    return res

def read_csv_file(path, delimiter=','):
    rows=[]
    try:
        with open(path, newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None:
                return []
            for row in reader:
                clean={}
                for k,v in row.items():
                    if k is None:
                        continue
                    clean[k]=v if v is not None else ""
                rows.append(clean)
    except FileNotFoundError as e:
        error_open_file(path, e)
    except NotADirectoryError as e:
        error_open_file(path, e)
    except IsADirectoryError as e:
        error_unknown_mimetype(path)
    except Exception as e:
        sys.stderr.write(str(e)+"\n")
        sys.exit(1)
    return rows

def read_json_file(path):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            content = f.read().strip()
            if not content:
                return []
            try:
                data = json.loads(content)
                if isinstance(data, list):
                    return data
                elif isinstance(data, dict):
                    return data
                else:
                    return data
            except json.JSONDecodeError:
                # Try jsonl
                rows=[]
                for line in content.splitlines():
                    line=line.strip()
                    if not line:
                        continue
                    try:
                        obj=json.loads(line)
                        rows.append(obj)
                    except:
                        first = line[0] if line else ''
                        sys.stderr.write(f"invalid character '{first}' looking for beginning of value\n")
                        sys.exit(1)
                return rows
    except FileNotFoundError as e:
        error_open_file(path, e)
    except NotADirectoryError as e:
        error_open_file(path, e)
    except IsADirectoryError as e:
        error_unknown_mimetype(path)
    return []

def read_jsonl_file(path):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            rows=[]
            for line in f:
                line=line.strip()
                if not line:
                    continue
                try:
                    obj=json.loads(line)
