def read_stdin_by_format(fmt, data_bytes):
    text = data_bytes.decode('utf-8', errors='replace')
    if fmt == "csv":
        f = io.StringIO(text)
        reader = csv.DictReader(f)
        rows=[]
        for row in reader:
            clean={}
            for k,v in row.items():
                if k is None:
                    continue
                clean[k]=v if v is not None else ""
            rows.append(clean)
        return rows
    elif fmt == "tsv":
        f = io.StringIO(text)
        reader = csv.DictReader(f, delimiter='\t')
        rows=[]
        for row in reader:
            clean={}
            for k,v in row.items():
                if k is None:
                    continue
                clean[k]=v if v is not None else ""
            rows.append(clean)
        return rows
    elif fmt == "json":
        text=text.strip()
        if not text:
            return []
        try:
            data = json.loads(text)
            if isinstance(data, list):
                return data
            elif isinstance(data, dict):
                return data
            else:
                return data
        except json.JSONDecodeError:
            rows=[]
            for line in text.splitlines():
                line=line.strip()
                if not line:
                    continue
                try:
                    obj=json.loads(line)
                    rows.append(obj)
                except:
                    first = line[0] if line else ''
                    sys.stderr.write(f"invalid character '{first}' looking for beginning of value\n")
                    sys.exit(1)
            return rows
    elif fmt == "jsonl" or fmt == "ndjson":
        rows=[]
        for line in text.splitlines():
            line=line.strip()
            if not line:
                continue
            try:
                obj=json.loads(line)
                rows.append(obj)
            except:
                first = line[0] if line else ''
                sys.stderr.write(f"invalid character '{first}' looking for beginning of value\n")
                sys.exit(1)
        return rows
    elif fmt == "logfmt":
        rows=[]
        for line in text.splitlines():
            line=line.strip()
            if not line:
                continue
            obj=parse_logfmt_line(line)
            rows.append(obj)
        return rows
    elif fmt == "parquet":
        with tempfile.NamedTemporaryFile(delete=False, suffix=".parquet") as tf:
            tf.write(data_bytes)
            tf.flush()
            tmp_path=tf.name
        try:
