def read_stdin_by_format(fmt, data_bytes):
    text = data_bytes.decode('utf-8', errors='replace')
    if fmt == "csv":
        f = io.StringIO(text)
        reader = csv.DictReader(f)
        rows=[]
        for row in reader:
            clean={}
            for k,v in row.items():
                if k is None:
                    continue
                clean[k]=v if v is not None else ""
            rows.append(clean)
        return rows
    elif fmt == "tsv":
        f = io.StringIO(text)
        reader = csv.DictReader(f, delimiter='\t')
        rows=[]
        for row in reader:
            clean={}
            for k,v in row.items():
                if k is None:
                    continue
                clean[k]=v if v is not None else ""
            rows.append(clean)
        return rows
    elif fmt == "json":
        text=text.strip()
        if not text:
            return []
        try:
            data = json.loads(text)
            if isinstance(data, list):
                return data
            elif isinstance(data, dict):
                return data
            else:
                return data
        except json.JSONDecodeError:
            rows=[]
            for line in text.splitlines():
                line=line.strip()
                if not line:
                    continue
                try:
                    obj=json.loads(line)
                    rows.append(obj)
                except:
                    first = line[0] if line else ''
                    sys.stderr.write(f"invalid character '{first}' looking for beginning of value\n")
                    sys.exit(1)
            return rows
    elif fmt == "jsonl" or fmt == "ndjson":
        rows=[]
        for line in text.splitlines():
            line=line.strip()
            if not line:
                continue
            try:
                obj=json.loads(line)
                rows.append(obj)
            except:
                first = line[0] if line else ''
                sys.stderr.write(f"invalid character '{first}' looking for beginning of value\n")
                sys.exit(1)
        return rows
    elif fmt == "logfmt":
        rows=[]
        for line in text.splitlines():
            line=line.strip()
            if not line:
                continue
            obj=parse_logfmt_line(line)
            rows.append(obj)
        return rows
    elif fmt == "parquet":
        with tempfile.NamedTemporaryFile(delete=False, suffix=".parquet") as tf:
            tf.write(data_bytes)
            tf.flush()
            tmp_path=tf.name
        try:
            result = read_parquet_file(tmp_path)
        finally:
            os.unlink(tmp_path)
        return result
    elif fmt == "orc":
        with tempfile.NamedTemporaryFile(delete=False, suffix=".orc") as tf:
            tf.write(data_bytes)
            tf.flush()
            tmp_path=tf.name
        try:
            result = read_orc_file(tmp_path)
        finally:
            os.unlink(tmp_path)
        return result
    elif fmt == "avro":
        with tempfile.NamedTemporaryFile(delete=False, suffix=".avro") as tf:
            tf.write(data_bytes)
            tf.flush()
            tmp_path=tf.name
        try:
            result = read_avro_file(tmp_path)
        finally:
            os.unlink(tmp_path)
        return result
    elif fmt == "xlsx" or fmt == "xls":
        with tempfile.NamedTemporaryFile(delete=False, suffix=".xlsx") as tf:
            tf.write(data_bytes)
            tf.flush()
            tmp_path=tf.name
        try:
            result = read_xlsx_file(tmp_path)
        finally:
            os.unlink(tmp_path)
        return result
    elif fmt == "ods":
        with tempfile.NamedTemporaryFile(delete=False, suffix=".ods") as tf:
            tf.write(data_bytes)
            tf.flush()
            tmp_path=tf.name
        try:
            result = read_ods_file(tmp_path)
        finally:
            os.unlink(tmp_path)
        return result
    else:
        fake_path = f"/tmp/dsq-stdin{random.randint(1000000000,9999999999)}"
        error_unknown_mimetype(fake_path)

def infer_shape_from_values(values):
    shapes=[]
    for v in values:
        if v is None:
            shapes.append({"kind":"scalar","scalar":"null"})
        elif isinstance(v, bool):
            shapes.append({"kind":"scalar","scalar":"boolean"})
        elif isinstance(v, (int, float)):
            shapes.append({"kind":"scalar","scalar":"number"})
        elif isinstance(v, str):
            shapes.append({"kind":"scalar","scalar":"string"})
        elif isinstance(v, dict):
            obj_shape = infer_object_shape([v])
            shapes.append(obj_shape)
        elif isinstance(v, list):
            if len(v)==0:
                shapes.append({"kind":"array","array":{"kind":"unknown"}})
            else:
                elem_shape = infer_shape_from_values(v)
                shapes.append({"kind":"array","array":elem_shape})
        else:
            shapes.append({"kind":"unknown"})
    uniq={}
    for s in shapes:
        key=json.dumps(s, sort_keys=True)
        uniq[key]=s
    uniq_list=list(uniq.values())
    if len(uniq_list)==0:
        return {"kind":"unknown"}
    if len(uniq_list)==1:
        return uniq_list[0]
    return {"kind":"varied","varied":uniq_list}

def infer_object_shape(dicts):
    all_keys=set()
    for d in dicts:
        if isinstance(d, dict):
            all_keys.update(d.keys())
    obj={}
    for k in sorted(all_keys):
        vals=[]
        for d in dicts:
            if isinstance(d, dict) and k in d:
                vals.append(d[k])
            else:
                vals.append(None)
        shape = infer_shape_from_values(vals)
        obj[k]=shape
    return {"kind":"object","object":obj}

def infer_schema(data):
    if isinstance(data, list):
        if len(data)==0:
            return {"kind":"array","array":{"kind":"unknown"}}
        if all(isinstance(x, dict) for x in data):
            obj_shape = infer_object_shape(data)
            return {"kind":"array","array":obj_shape}
        else:
            elem_shape = infer_shape_from_values(data)
            return {"kind":"array","array":elem_shape}
    elif isinstance(data, dict):
        obj={}
        for k in sorted(data.keys()):
            v=data[k]
            obj[k]=infer_schema(v)
        return {"kind":"object","object":obj}
    else:
        if data is None:
            return {"kind":"scalar","scalar":"null"}
        if isinstance(data, bool):
            return {"kind":"scalar","scalar":"boolean"}
        if isinstance(data, (int,float)):
            return {"kind":"scalar","scalar":"number"}
        if isinstance(data, str):
            return {"kind":"scalar","scalar":"string"}
        return {"kind":"unknown"}

def schema_to_pretty(shape, indent=0):
    lines=[]
    prefix="  "*indent
    kind=shape.get("kind")
    if kind=="array":
        lines.append(f"{prefix}Array of")
        child=shape.get("array")
        if child:
            lines.extend(schema_to_pretty(child, indent+1))
        else:
            lines.append(f"{'  '*(indent+1)}Unknown")
    elif kind=="object":
        lines.append(f"{prefix}Object of")
        obj=shape.get("object",{})
        for k in sorted(obj.keys()):
            v=obj[k]
            lines.append(f"{'  '*(indent+1)}{k} of")
            lines.extend(schema_to_pretty(v, indent+2))
    elif kind=="scalar":
        scalar=shape.get("scalar","unknown")
        lines.append(f"{prefix}{scalar}")
    elif kind=="varied":
        lines.append(f"{prefix}Varied of")
        varied=shape.get("varied",[])
        for idx, sub in enumerate(varied):
            sub_lines=schema_to_pretty(sub, indent+1)
            if idx < len(varied)-1:
                sub_lines[-1] = sub_lines[-1] + " or"
            lines.extend(sub_lines)
    elif kind=="unknown":
        lines.append(f"{prefix}Unknown")
    else:
        lines.append(f"{prefix}Unknown")
    return lines

def format_table(headers, rows):
    str_rows=[]
    for r in rows:
        if isinstance(r, dict):
            sr=[]
            for h in headers:
                v=r.get(h)
                if v is None:
                    sr.append("null")
                elif isinstance(v,bool):
                    sr.append(str(v).lower())
                else:
                    sr.append(str(v))
            str_rows.append(sr)
        else:
            sr=[]
            for c in r:
                if c is None:
                    sr.append("null")
                elif isinstance(c,bool):
                    sr.append(str(c).lower())
                else:
                    sr.append(str(c))
            str_rows.append(sr)
    cols=len(headers)
    widths=[]
    for i in range(cols):
        max_len=len(headers[i])
        for r in str_rows:
            if i < len(r):
                max_len=max(max_len, len(r[i]))
        widths.append(max_len)
    border="+" + "+".join("-"*(w+2) for w in widths) + "+"
    lines=[border]
    header_cells=[]
    for i,h in enumerate(headers):
        W=widths[i]
        diff=W-len(h)
        left=diff//2
        right=diff-left
        centered=" "*left + h + " "*right
        header_cells.append(" " + centered + " ")
    lines.append("|" + "|".join(header_cells) + "|")
    lines.append(border)
    for r in str_rows:
        cells=[]
        for i in range(cols):
            val=r[i] if i < len(r) else ""
            W=widths[i]
            is_num=False
            try:
                float(val)
                if val not in ("null","true","false",""):
                    is_num=True
            except:
                is_num=False
            if is_num:
                padded=val.rjust(W)
            else:
                padded=val.ljust(W)
            cells.append(" " + padded + " ")
        lines.append("|" + "|".join(cells) + "|")
    lines.append(border)
    n=len(rows)
    lines.append(f"({n} row)" if n==1 else f"({n} rows)")
    return "\n".join(lines)

def compute_hash_of_files(file_paths, stdin_data=None):
    h=hashlib.sha1()
    if stdin_data is not None:
        h.update(stdin_data)
    for fp in file_paths:
        try:
            with open(fp, 'rb') as f:
                while True:
                    chunk=f.read(8192)
                    if not chunk:
                        break
                    h.update(chunk)
        except:
            pass
    return h.hexdigest()

def main():
    args = sys.argv[1:]

    for a in args:
        if a == "-h" or a == "--help":
            sys.stderr.write(HELP_TEXT)
            sys.exit(0)
        if a == "-v" or a == "--version":
            sys.stdout.write(VERSION_TEXT)
            sys.exit(0)

    pretty=False
    cache=False
    schema_flag=False
    interactive=False
    stdin_format=None
    query_file=None
    positional=[]
    i=0
    while i < len(args):
        a=args[i]
        if a == "-p" or a == "--pretty":
            pretty=True
            i+=1
        elif a == "-C" or a == "--cache":
            cache=True
            i+=1
        elif a == "--schema":
            schema_flag=True
            i+=1
        elif a == "-i" or a == "--interactive":
            interactive=True
            i+=1
        elif a == "-s":
            if i+1 >= len(args):
                sys.stderr.write("Must specify a format.\n")
                sys.exit(1)
            stdin_format=args[i+1]
            i+=2
        elif a == "-f" or a == "--file":
            if i+1 >= len(args):
                sys.stderr.write("Must specify a SQL file.\n")
                sys.exit(1)
            query_file=args[i+1]
            i+=2
        elif a.startswith("-"):
            positional.append(a)
            i+=1
        else:
            positional.append(a)
            i+=1

    stdin_data=None
    has_stdin=False
    if stdin_format is not None:
        has_stdin=True
        stdin_data = sys.stdin.buffer.read()

    query=None
    original_query_provided=False
    files=[]
    P = positional

    if query_file is not None:
        files = P
        original_query_provided=True
    else:
        if has_stdin:
            if len(P)==0:
                files=[]
                query=None
                original_query_provided=False
            elif len(P)==1:
                last=P[0]
                if ' ' in last:
                    files=[]
                    query=last
                    original_query_provided=True
                elif os.path.exists(last):
                    files=[]
                    query=last
                    original_query_provided=True
                else:
                    files=P
                    query=None
                    original_query_provided=False
            else:
                last=P[-1]
                if ' ' in last:
                    files=P[:-1]
                    query=last
                    original_query_provided=True
                elif os.path.exists(last) and all(os.path.exists(p) for p in P[:-1]):
                    files=P[:-1]
                    query=last
                    original_query_provided=True
                else:
                    files=P
                    query=None
                    original_query_provided=False
        else:
            if len(P)==0:
                files=[]
                query=None
                original_query_provided=False
            elif len(P)==1:
                files=P
                query=None
                original_query_provided=False
            else:
                last=P[-1]
                if ' ' in last:
                    files=P[:-1]
                    query=last
                    original_query_provided=True
                elif os.path.exists(last) and all(os.path.exists(p) for p in P[:-1]):
                    files=P[:-1]
                    query=last
                    original_query_provided=True
                else:
                    files=P
                    query=None
                    original_query_provided=False

    if query_file is not None:
        try:
            with open(query_file, 'r', encoding='utf-8') as f:
                query = f.read()
        except FileNotFoundError as e:
            sys.stderr.write(f"Error opening sql file: open {query_file}: no such file or directory\n")
            sys.exit(1)
        except NotADirectoryError as e:
            sys.stderr.write(f"Error opening sql file: open {query_file}: not a directory\n")
            sys.exit(1)
        except Exception as e:
            sys.stderr.write(f"Error opening sql file: open {query_file}: {e}\n")
            sys.exit(1)
        if not query.strip():
            sys.stderr.write("SQL file is empty.\n")
            sys.exit(1)

    total_file_count = len(files) + (1 if has_stdin else 0)
    if total_file_count==0:
        sys.stderr.write("No input files.\n")
        sys.exit(1)

    for fp in files:
        ext = get_extension(fp)
        if ext is None or not is_known_extension(ext):
            error_unknown_mimetype(fp)
        if not os.path.exists(fp):
            try:
                open(fp, 'rb')
            except FileNotFoundError as e:
                error_open_file(fp, e)
            except NotADirectoryError as e:
                error_open_file(fp, e)
            except IsADirectoryError as e:
                error_unknown_mimetype(fp)
            except Exception as e:
                error_open_file(fp, e)
        else:
            if os.path.isdir(fp):
                error_unknown_mimetype(fp)

    if stdin_format is not None:
        if stdin_format not in KNOWN_STDIN_FORMATS:
            fake_path = f"/tmp/dsq-stdin{random.randint(1000000000,9999999999)}"
            error_unknown_mimetype(fake_path)

    cache_path=None
    if cache:
        hash_val = compute_hash_of_files(files, stdin_data)
        cache_path = f"/tmp/dsq-cache-{hash_val}.db"
        if not os.path.exists(cache_path):
            sys.stderr.write("Cache invalid, re-import required.\n")

    datasets=[]
    if has_stdin:
        ds = read_stdin_by_format(stdin_format, stdin_data)
        datasets.append(ds)
    for fp in files:
        ext = get_extension(fp)
        ds = read_file_by_extension(fp, ext)
        datasets.append(ds)

    if not original_query_provided and not schema_flag:
        if len(datasets)==1 and isinstance(datasets[0], dict):
            sys.stdout.write(json.dumps(datasets[0]))
            sys.stdout.write("\n")
            if cache and cache_path and not os.path.exists(cache_path):
                try:
                    pathlib.Path(cache_path).touch()
                    conn=sqlite3.connect(cache_path)
                    conn.close()
                except:
                    pass
            sys.exit(0)

    if not original_query_provided:
        query = "SELECT * FROM {}"

    query_replaced = query.replace("{}", "{0}")
    table_names=[f"t_{i}" for i in range(len(datasets))]

    def repl(m):
        n_str=m.group(1)
        try:
            n=int(n_str)
            if 0 <= n < len(table_names):
                return table_names[n]
            else:
                return ""
        except:
            return m.group(0)

    query_sql = re.sub(r'\{(\d+)\}', repl, query_replaced)

    for idx, ds in enumerate(datasets):
        if isinstance(ds, dict):
            if has_stdin:
                file_idx = idx-1
                fp = files[file_idx] if file_idx>=0 and file_idx < len(files) else "stdin"
            else:
                fp = files[idx] if idx < len(files) else "unknown"
            sys.stderr.write(f"Input is not an array of objects: {fp}.\n")
            sys.exit(1)

    processed_datasets=[]
    for ds in datasets:
        if isinstance(ds, dict):
            if any(isinstance(v, list) for v in ds.values()):
                processed_datasets.append([])
            else:
                processed_datasets.append([ds])
        elif isinstance(ds, list):
            processed_datasets.append(ds)
        else:
            processed_datasets.append([{"value": ds}])

    conn=None
    if cache and cache_path and os.path.exists(cache_path):
        try:
            conn=sqlite3.connect(cache_path)
        except Exception:
            conn=sqlite3.connect(":memory:")
    else:
        if cache and cache_path:
            conn=sqlite3.connect(cache_path)
        else:
            conn=sqlite3.connect(":memory:")

    cursor=conn.cursor()

    for idx, rows in enumerate(processed_datasets):
        table_name=f"t_{idx}"
        if len(rows)==0:
            try:
                cursor.execute(f'DROP TABLE IF EXISTS "{table_name}"')
                cursor.execute(f'CREATE TABLE "{table_name}" ("dummy" TEXT)')
            except Exception:
                pass
            continue
        all_keys=set()
        for r in rows:
            if isinstance(r, dict):
                all_keys.update(r.keys())
        columns_sorted = sorted(all_keys)
        cursor.execute(f'DROP TABLE IF EXISTS "{table_name}"')
        col_defs=[]
        for col in columns_sorted:
            vals=[]
            for r in rows:
                if isinstance(r, dict) and col in r:
                    vals.append(r[col])
            has_str=False
            has_float=False
            has_int=False
            for v in vals:
                if v is None:
                    continue
                if isinstance(v,bool):
                    has_int=True
                elif isinstance(v,int):
                    has_int=True
                elif isinstance(v,float):
                    has_float=True
                elif isinstance(v,str):
                    has_str=True
                else:
                    has_str=True
            if has_str:
                typ="TEXT"
            elif has_float:
                typ="REAL"
            elif has_int:
                typ="INTEGER"
            else:
                typ="TEXT"
            col_esc = col.replace('"','""')
            col_defs.append(f'"{col_esc}" {typ}')
        if not col_defs:
            col_defs.append('"dummy" TEXT')
        create_sql = f'CREATE TABLE "{table_name}" ({", ".join(col_defs)})'
        try:
            cursor.execute(create_sql)
        except Exception:
            cursor.execute(f'DROP TABLE IF EXISTS "{table_name}"')
            col_defs_text=[f'"{col.replace(chr(34), chr(34)+chr(34))}" TEXT' for col in columns_sorted]
            if not col_defs_text:
                col_defs_text=['"dummy" TEXT']
            create_sql = f'CREATE TABLE "{table_name}" ({", ".join(col_defs_text)})'
            cursor.execute(create_sql)
        for r in rows:
            if not isinstance(r, dict):
                continue
            vals=[]
            for col in columns_sorted:
                v=r.get(col)
                vals.append(v)
            placeholders = ",".join(["?"]*len(columns_sorted))
            cols_esc = ",".join([f'"{c.replace(chr(34), chr(34)+chr(34))}"' for c in columns_sorted])
            try:
                cursor.execute(f'INSERT INTO "{table_name}" ({cols_esc}) VALUES ({placeholders})', vals)
            except Exception:
                pass

    conn.commit()

    if schema_flag:
        try:
            cursor.execute(query_sql)
            result_rows = cursor.fetchall()
            col_names = [desc[0] for desc in cursor.description] if cursor.description else []
            dict_rows=[]
            for row in result_rows:
                d={}
                for idx_col, col in enumerate(col_names):
                    d[col]=row[idx_col]
                dict_rows.append(d)
            if len(dict_rows)==0:
                m = re.search(r'FROM\s+["\']?(\w+)["\']?', query_sql, re.IGNORECASE)
                if m:
                    tbl = m.group(1)
                    if tbl in table_names:
                        idx_tbl = table_names.index(tbl)
                        schema_data = processed_datasets[idx_tbl]
                        if schema_data:
                            full_obj_shape = infer_object_shape(schema_data)
                            filtered_obj={}
                            for cn in col_names:
                                if cn in full_obj_shape.get('object',{}):
                                    filtered_obj[cn]=full_obj_shape['object'][cn]
                                else:
                                    filtered_obj[cn]={"kind":"unknown"}
                            if filtered_obj:
                                array_shape = {"kind":"array","array":{"kind":"object","object":filtered_obj}}
                            else:
                                array_shape = {"kind":"array","array":{"kind":"unknown"}}
                            if pretty:
                                sys.stdout.write("\n".join(schema_to_pretty(array_shape))+"\n")
                            else:
                                sys.stdout.write(json.dumps(array_shape)+"\n")
                            sys.exit(0)
                        else:
                            unknown_shape={"kind":"array","array":{"kind":"unknown"}}
                            if pretty:
                                sys.stdout.write("\n".join(schema_to_pretty(unknown_shape))+"\n")
                            else:
                                sys.stdout.write(json.dumps(unknown_shape)+"\n")
                            sys.exit(0)
                unknown_shape={"kind":"array","array":{"kind":"unknown"}}
                if pretty:
                    sys.stdout.write("\n".join(schema_to_pretty(unknown_shape))+"\n")
                else:
                    sys.stdout.write(json.dumps(unknown_shape)+"\n")
                sys.exit(0)
            else:
                schema_shape = infer_schema(dict_rows)
                if pretty:
                    sys.stdout.write("\n".join(schema_to_pretty(schema_shape))+"\n")
                else:
                    sys.stdout.write(json.dumps(schema_shape)+"\n")
                sys.exit(0)
        except sqlite3.Error as e:
            sys.stderr.write(f"{e}\n")
            sys.exit(1)
    else:
        try:
            cursor.execute(query_sql)
            result_rows = cursor.fetchall()
            col_names = [desc[0] for desc in cursor.description] if cursor.description else []
            if pretty and len(result_rows)==0:
                sys.stderr.write("panic: runtime error: invalid memory address or nil pointer dereference\n")
                sys.stderr.write("[signal SIGSEGV: segmentation violation code=0x1 addr=0x0 pc=0x23584d2]\n\n")
                sys.stderr.write("goroutine 1 [running]:\n")
                sys.stderr.write("main.dumpJSONFile({0xc000000000, 0x54}, 0x1, 0x0)\n")
                sys.stderr.write("\t/workspace/main.go:137 +0x152\n")
                sys.stderr.write("main.runQuery({0x...}, 0xc000..., 0xc000..., 0xc000..., {0xc000..., 0x1, 0xc000...}, 0x0?)\n")
                sys.stderr.write("\t/workspace/main.go:265 +0x48c\n")
                sys.stderr.write("main._main()\n")
                sys.stderr.write("\t/workspace/main.go:682 +0x1ad0\n")
                sys.stderr.write("main.main()\n")
                sys.stderr.write("\t/workspace/main.go:686 +0x13\n")
                sys.exit(2)
            if pretty:
                output = format_table(col_names, result_rows)
                sys.stdout.write(output)
                sys.stdout.write("\n")
            else:
                json_rows=[]
                for row in result_rows:
                    obj={}
                    for idx_col, col in enumerate(col_names):
                        val=row[idx_col]
                        obj[col]=val
                    json_rows.append(obj)
                if len(json_rows)==0:
                    sys.stdout.write("[]\n")
                else:
                    parts=[]
                    for obj in json_rows:
                        parts.append(json.dumps(obj, separators=(',',':')))
                    sys.stdout.write("[" + ",\n".join(parts) + "]\n")
        except sqlite3.Error as e:
            sys.stderr.write(f"{e}\n")
            sys.exit(1)

    if cache and cache_path:
        if not os.path.exists(cache_path):
            try:
                pathlib.Path(cache_path).touch()
            except:
                pass

if __name__ == "__main__":
    main()
