def parse_logfmt_line(line):
    res={}
    i=0
    n=len(line)
    while i<n:
        while i<n and line[i]==' ':
            i+=1
        if i>=n:
            break
        key_start=i
        while i<n and line[i]!='=' and line[i]!=' ':
            i+=1
        if i>=n or line[i]!='=':
            while i<n and line[i]!=' ':
                i+=1
            continue
        key=line[key_start:i]
        i+=1
        if i>=n:
            res[key]=""
            break
        if line[i]=='"':
            i+=1
            val_start=i
            while i<n:
                if line[i]=='"' and (i==0 or line[i-1]!='\\'):
                    break
                i+=1
            val=line[val_start:i]
            if i<n and line[i]=='"':
                i+=1
            res[key]=val
        else:
            val_start=i
            while i<n and line[i]!=' ':
                i+=1
            val=line[val_start:i]
