                repeat = cell_elem.get('{urn:oasis:names:tc:opendocument:xmlns:table:1.0}number-columns-repeated')
                try:
                    repeat = int(repeat) if repeat else 1
                except:
                    repeat=1
                p_elem = cell_elem.find('text:p', ns)
                if p_elem is not None and p_elem.text is not None:
                    val = p_elem.text
                else:
                    ps = cell_elem.findall('text:p', ns)
                    if ps:
                        val = ''.join([p.text if p.text else '' for p in ps])
                    else:
                        val = ""
                for _ in range(repeat):
                    cells.append(val)
            rows.append(cells)
        sheets_data[name]=rows

    if len(sheets_data)==1:
        name = list(sheets_data.keys())[0]
        rows = sheets_data[name]
        if len(rows)==0:
            return []
        header = rows[0]
        data_rows = rows[1:]
        result=[]
        for dr in data_rows:
            obj={}
            for i,h in enumerate(header):
                if i < len(dr):
                    obj[h]=dr[i]
                else:
                    obj[h]=""
            result.append(obj)
        return result
    else:
        result={}
        for name, rows in sheets_data.items():
            if len(rows)==0:
                result[name]=[]
                continue
            header=rows[0]
            data_rows=rows[1:]
            arr=[]
            for dr in data_rows:
                obj={}
                for i,h in enumerate(header):
                    if i < len(dr):
                        obj[h]=dr[i]
                    else:
                        obj[h]=""
                arr.append(obj)
            result[name]=arr
        return result

def read_avro_file(path):
    try:
        data = pathlib.Path(path).read_bytes()
    except FileNotFoundError as e:
        error_open_file(path, e)
    except NotADirectoryError as e:
        error_open_file(path, e)
    except IsADirectoryError as e:
        error_unknown_mimetype(path)

    def read_long(buf, pos):
        n=0
        shift=0
        while True:
            if pos>=len(buf):
                raise Exception("EOF")
            b=buf[pos]
            pos+=1
            n|=(b&0x7F)<<shift
            if not (b&0x80):
                break
            shift+=7
        val=(n>>1) ^ -(n&1)
        return val,pos

    def read_bytes_inner(buf,pos):
        l,pos=read_long(buf,pos)
        if l<0:
            raise Exception("neg")
        b=buf[pos:pos+l]
        pos+=l
        return b,pos

    def read_string_inner(buf,pos):
        b,pos=read_bytes_inner(buf,pos)
        return b.decode('utf-8'),pos

    def snappy_decompress_block(block):
        if len(block)<4:
            return b""
        comp = block[:-4]
        i=0
        length=0
        shift=0
        while True:
            if i>=len(comp):
                break
            b=comp[i]
            i+=1
            length |= (b & 0x7F) << shift
            if not (b & 0x80):
                break
            shift+=7
        src = comp[i:]
        dst = bytearray()
        p=0
        while p < len(src):
            tag = src[p]
            p+=1
            typ = tag & 0x03
            if typ == 0:
                l = (tag >> 2)
                if l < 60:
                    l+=1
                else:
                    nbytes = l - 59
                    extra=0
                    for j in range(nbytes):
                        if p+j >= len(src):
                            break
                        extra |= src[p+j] << (j*8)
                    p+=nbytes
                    l = extra+1
                if p+l > len(src):
                    dst.extend(src[p:])
                    break
                dst.extend(src[p:p+l])
                p+=l
            elif typ == 1:
                l = ((tag >> 2) & 0x07) + 4
                if p>=len(src):
                    break
                off = ((tag >> 5) << 8) | src[p]
                p+=1
                for _ in range(l):
                    if off>len(dst) or off<=0:
                        break
                    dst.append(dst[-off])
            elif typ == 2:
                l = (tag >> 2) + 1
                if p+1>=len(src):
                    break
                off = src[p] | (src[p+1] << 8)
                p+=2
                for _ in range(l):
                    if off>len(dst) or off<=0:
                        break
                    dst.append(dst[-off])
            else:
                l = (tag >> 2) + 1
                if p+3>=len(src):
                    break
                off = src[p] | (src[p+1] << 8) | (src[p+2] << 16) | (src[p+3] << 24)
                p+=4
                for _ in range(l):
                    if off>len(dst) or off<=0:
                        break
                    dst.append(dst[-off])
        return bytes(dst)

    if len(data)<4 or data[0:3]!=b'Obj' or data[3]!=1:
        snippet = data[:20].decode('utf-8', errors='replace').replace('\n','\\n').replace('\r','\\r')
        sys.stderr.write(f'cannot create OCFReader: cannot read OCF header with invalid magic bytes: "{snippet}"\n')
        sys.exit(1)

    pos=4
    try:
        cnt,pos=read_long(data,pos)
    except Exception as e:
        sys.stderr.write(f"cannot create OCFReader: {e}\n")
        sys.exit(1)
    schema=None
    codec=b'null'
    for _ in range(cnt):
        try:
            k,pos=read_string_inner(data,pos)
            v,pos=read_bytes_inner(data,pos)
        except Exception as e:
            sys.stderr.write(f"cannot create OCFReader: {e}\n")
            sys.exit(1)
        if k=='avro.schema':
            try:
                schema=json.loads(v.decode())
            except:
                schema=None
        elif k=='avro.codec':
            codec=v
    try:
        end,pos=read_long(data,pos)
        sync=data[pos:pos+16]
        pos+=16
    except Exception as e:
        sys.stderr.write(f"cannot create OCFReader: {e}\n")
        sys.exit(1)

    if schema is None:
        sys.stderr.write("cannot create OCFReader: no schema\n")
        sys.exit(1)

    def decode_type(buf, p, typ):
        if isinstance(typ, list):
            idx, p = read_long(buf, p)
            return decode_type(buf, p, typ[idx])
        if isinstance(typ, dict):
            t=typ.get('type')
            if t=='record':
                out={}
                for field in typ.get('fields',[]):
                    name=field['name']
                    ftyp=field['type']
                    val,p = decode_type(buf, p, ftyp)
                    out[name]=val
                return out,p
            elif t=='array':
                arr=[]
                while True:
                    count,p = read_long(buf,p)
                    if count==0:
                        break
                    if count<0:
                        count=-count
                        _,p = read_long(buf,p)
                    for _ in range(count):
                        val,p = decode_type(buf,p, typ.get('items'))
                        arr.append(val)
                return arr,p
            elif t=='map':
                m={}
                while True:
                    count,p = read_long(buf,p)
                    if count==0:
                        break
                    if count<0:
                        count=-count
                        _,p = read_long(buf,p)
                    for _ in range(count):
                        key,p = read_string_inner(buf,p)
                        val,p = decode_type(buf,p, typ.get('values'))
                        m[key]=val
                return m,p
            else:
                raise Exception(f"unsupported {typ}")
        if typ=='null':
            return None,p
        if typ=='string':
            s,p = read_string_inner(buf,p)
            return s,p
        if typ=='long':
            v,p = read_long(buf,p)
            return v,p
        if typ=='int':
            v,p = read_long(buf,p)
            return v,p
        if typ=='double':
            import struct
            v = struct.unpack('<d', buf[p:p+8])[0]
            p+=8
            return v,p
        if typ=='float':
            import struct
            v = struct.unpack('<f', buf[p:p+4])[0]
            p+=4
            return v,p
        if typ=='boolean':
            b=buf[p]
            p+=1
            return bool(b),p
        if typ=='bytes':
            b,p = read_bytes_inner(buf,p)
            return b,p
        raise Exception(f"unknown {typ}")

    rows=[]
    while pos < len(data):
        try:
            count,pos=read_long(data,pos)
        except:
            break
        if count==0:
            break
        try:
            size,pos=read_long(data,pos)
        except:
            break
        if pos+size > len(data):
            break
        block=data[pos:pos+size]
        pos+=size
        if pos+16 <= len(data):
            pos+=16
        if codec==b'snappy':
            try:
                decomp = snappy_decompress_block(block)
            except Exception as e:
                sys.stderr.write(f"snappy error: {e}\n")
                sys.exit(1)
        elif codec==b'deflate':
            import zlib
            try:
                decomp = zlib.decompress(block)
            except Exception as e:
                sys.stderr.write(f"deflate error: {e}\n")
                sys.exit(1)
        else:
            decomp = block
        dpos=0
        for _ in range(count):
            try:
                rec,dpos = decode_type(decomp, dpos, schema)
                rows.append(rec)
            except Exception:
                break
    return rows

